#include <bits/stdc++.h>
using namespace std;

long modInverse(long a, long m) {
    long result = 1, base = a, exp = m - 2;
    while (exp > 0) {
        if (exp & 1) result = (result * base) % m;
        base = (base * base) % m;
        exp >>= 1;
    }
    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    const long MOD = 998244353;

    int n, k;
    long long l;
    cin >> n >> k >> l;
    l %= MOD;

