    }

    invFact[0] = 1;
    for (int i = 1; i < (int)invFact.size(); i++) {
        invFact[i] = modInverse(fact[i], MOD);
    }

    long long total = 0;
    for (int i = k; i <= n; i++) {
        long long sum = 0;
        for (int s = 0, sign = 1; s <= n - i; s++, sign = -sign) {
            long long val = c[s][n - i];
            val = (val * pow2[s]) % MOD;
